// Demo: Double-blind trials - related Reference Manager technology
(function(){'use strict';
var DATA={"value": 93.0, "from": "F", "to": "C", "label": "Double-blind trials - related Reference Manager technology"};

var T={m:1,km:1000,cm:0.01,mm:0.001,mi:1609.344,ft:0.3048,in:0.0254,
  kg:1,g:0.001,lb:0.45359237,oz:0.028349523125,
  s:1,min:60,h:3600,day:86400,
  C:'temp',F:'temp',K:'temp'};
function conv(v,from,to){
  if(T[from]==='temp'||T[to]==='temp'){
    var c=from==='C'?v:from==='F'?(v-32)*5/9:v-273.15;
    return to==='C'?c:to==='F'?c*9/5+32:c+273.15;}
  return v*T[from]/T[to];}
var r=conv(DATA.value,DATA.from,DATA.to);
console.log(DATA.value+' '+DATA.from+' = '+r.toFixed(6)+' '+DATA.to+'  ('+DATA.label+')');
})();

